use vstd::prelude::*;

verus! {
    fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> (result: Vec<f32>)
        ensures
            result.len() == arr.len() + values.len(),
            forall|i: nat| 0 <= i < arr.len() ==> result[i] == arr[i],
            forall|j: nat| 0 <= j < values.len() ==> result[arr.len() + j] == values[j],
    {
        let mut result: Vec<f32> = Vec::new();
        
        // Append elements from the first vector
        let mut i: nat = 0;
        while i < arr.len()
            invariant
                i <= arr.len(),
                result.len() == i,
                forall|k: nat| 0 <= k < i ==> result[k] == arr[k],
            decreases arr.len() - i,
        {
            result.push(arr[i]);
            i = i + 1;
        }

        // Append elements from the second vector
        let mut j: nat = 0;
        while j < values.len()
            invariant
                j <= values.len(),
                result.len() == arr.len() + j,
                forall|k: nat| 0 <= k < j ==> result[arr.len() + k] == values[k],
            decreases values.len() - j,
        {
            result.push(values[j]);
            j = j + 1;
        }

        result
    }
}
